CREATE COLUMN TABLE "TEST_AP"."SRA3" ("ActionCode" INTEGER CS_INT NOT NULL , "RecipCode" INTEGER CS_INT NOT NULL , "ObjType" NVARCHAR(20), "ObjCode" NVARCHAR(50), "Name" NVARCHAR(155), "SendInter" NVARCHAR(1) DEFAULT 'N', "SendEmail" NVARCHAR(1) DEFAULT 'N', "SendSMS" NVARCHAR(1) DEFAULT 'N', "Email" NVARCHAR(100), "Number" NVARCHAR(100), "AttachDAG" NVARCHAR(1) DEFAULT 'N', "AttachPDF" NVARCHAR(1) DEFAULT 'N', "AttachHTML" NVARCHAR(1) DEFAULT 'N', "AttachXML" NVARCHAR(1) DEFAULT 'N', "ShowResult" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("ActionCode", "RecipCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "SRA3_USER" ON "TEST_AP"."SRA3" ( "Name" ASC )